export const articles:Article[]=articleDrafts.map(article=>article.primaryKeyword?article:{...article,...legacyKeywordMap[article.slug],updatedAt:article.updatedAt??(article.draft?undefined:'2026-08-18')});

export const categoryLabels:ArticleCategory[]=['Panduan Equipment','Rental & Operasional','Maintenance','Keselamatan Kerja'];
export const isPublished=(article:Article,now=new Date())=>!article.draft&&new Date(`${article.publishedAt}T00:00:00+07:00`)<=now;
const retiredProductArticles=new Set(['material-handling-dan-produktivitas-gudang','memilih-genset-untuk-proyek-dan-industri']);
export const publishedArticles=(now=new Date())=>articles.filter(a=>isPublished(a,now)&&!retiredProductArticles.has(a.slug)).sort((a,b)=>b.publishedAt.localeCompare(a.publishedAt));
export const getRelatedArticles=(article:Article,limit=3)=>{
 const active=publishedArticles().filter(a=>a.slug!==article.slug);
 return active.sort((a,b)=>{
  const explicitA=article.relatedArticles.includes(a.slug)?1:0,explicitB=article.relatedArticles.includes(b.slug)?1:0;
  const categoryA=a.category===article.category?1:0,categoryB=b.category===article.category?1:0;
  const tagsA=a.tags.filter(t=>article.tags.includes(t)).length,tagsB=b.tags.filter(t=>article.tags.includes(t)).length;
  return (explicitB-explicitA)||(categoryB-categoryA)||(tagsB-tagsA)||b.publishedAt.localeCompare(a.publishedAt);
 }).slice(0,limit);
};
